\mathsf{Ax}_{\mathsf{bool}}
=
\{C\sqsubseteq C,C\sqsubseteq\top,\bot\sqsubseteq C:C\in\mathsf{Con}_{\mathsf{HALC}}\}
\cup
\{C\sqcap D\sqsubseteq C,C\sqcap D\sqsubseteq D:C,D\in\mathsf{Con}_{\mathsf{HALC}}\}
\cup
\{C\sqcap\neg C\sqsubseteq\bot,\ \top\sqsubseteq C\sqcup\neg C:C\in\mathsf{Con}_{\mathsf{HALC}}\}
\cup
\{C\sqsubseteq C\sqcup D,\ D\sqsubseteq C\sqcup D:C,D\in\mathsf{Con}_{\mathsf{HALC}}\}.

(C\sqcap D)^{\mathcal I}
=
C^{\mathcal I}\cap D^{\mathcal I},

(C\sqcup D)^{\mathcal I}
=
C^{\mathcal I}\cup D^{\mathcal I},

(\forall R.C)^{\mathcal I}
=
\{x\in\Delta:\forall y\in\Delta\ ((x,y)\in\iota_R(R)\Rightarrow y\in C^{\mathcal I})\},

(\exists R.C)^{\mathcal I}
=
\{x\in\Delta:\exists y\in\Delta\ ((x,y)\in\iota_R(R)\ \text{且}\ y\in C^{\mathcal I})\}.
